import openpyxl,json,math,statistics as st
wb=openpyxl.load_workbook('expression.xlsx',data_only=True);d=wb['Data'];t=wb['Task']
hdr={d.cell(1,c).value:c for c in range(1,d.max_column+1)}
rows={d.cell(r,1).value:r for r in range(2,d.max_row+1)}
exp=json.load(open('out_build.json'))['expected']
bad=0
for i,r in enumerate(range(11,21)):
  pid=t.cell(r,1).value; dr=rows[pid]
  ctl=[];trt=[]
  for c in range(3,13):
    v=d.cell(dr,hdr[t.cell(10,c).value]).value
    a=openpyxl.utils.get_column_letter(c)+str(r)
    e=exp.get('Task!'+a, exp.get(a,'MISSING'))
    if (v in (None,'') and e not in (None,'')) or (v not in (None,'') and (e in (None,'MISSING') or abs(e-v)>1e-9)): bad+=1;print('lookup',a,v,e)
    if isinstance(v,(int,float)): (ctl if t.cell(9,c).value=='Control' else trt).append(v)
  cm,tm=st.mean(ctl),st.mean(trt); fc=tm/cm
  sc=openpyxl.utils.get_column_letter(2+i)
  for a,val in [(sc+'24',cm),(sc+'25',st.pstdev(ctl)),(sc+'26',tm),(sc+'27',st.pstdev(trt)),('C'+str(32+i),fc),('D'+str(32+i),math.log2(fc))]:
    e=exp.get('Task!'+a, exp.get(a))
    if e is None or abs(e-val)>1e-6*max(1,abs(val)): bad+=1;print('stat',a,val,e)
print('mismatches',bad); print(list(exp)[:5])
"
